import{_ as e,o as r,c as a,ae as d}from"./chunks/framework.BX6FPmO9.js";const p=JSON.parse('{"title":"套件與 React 支援度","description":"","frontmatter":{},"headers":[],"relativePath":"conventions/packages-react.md","filePath":"conventions/packages-react.md"}'),o={name:"conventions/packages-react.md"};function c(n,t,s,i,h,l){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="套件與-react-支援度" tabindex="-1">套件與 React 支援度 <a class="header-anchor" href="#套件與-react-支援度" aria-label="Permalink to &quot;套件與 React 支援度&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>本專案以 <strong>React 18</strong> 為基準。新增或升級套件時，請確認其 React 支援度並更新本表。</p><hr><h2 id="專案基準" tabindex="-1">專案基準 <a class="header-anchor" href="#專案基準" aria-label="Permalink to &quot;專案基準&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>版本</th></tr></thead><tbody><tr><td><strong>React</strong></td><td>^18.3.1（見 package.json）</td></tr><tr><td><strong>React DOM</strong></td><td>^18.3.1</td></tr><tr><td><strong>Node</strong></td><td>&gt;= 20（engines）</td></tr></tbody></table><p>升級 React 大版（如 18→19）前，請依下方清單逐項確認 peer 與相容性，並跑 <code>pnpm run lint:ci</code>、<code>pnpm run test</code>。</p><hr><h2 id="與-react-直接相關的套件" tabindex="-1">與 React 直接相關的套件 <a class="header-anchor" href="#與-react-直接相關的套件" aria-label="Permalink to &quot;與 React 直接相關的套件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>套件</th><th>用途</th><th>React 支援／備註</th></tr></thead><tbody><tr><td><strong>@remix-run/react</strong></td><td>路由與資料</td><td>Remix 2 要求 React 18</td></tr><tr><td><strong>@radix-ui/react-scroll-area</strong></td><td>UI 元件</td><td>peer: ^16.8 || ^17 || ^18 || ^19</td></tr><tr><td><strong>@radix-ui/react-slot</strong></td><td>元件組合</td><td>同上，Radix 系列皆支援 16–19</td></tr><tr><td><strong>react</strong>, <strong>react-dom</strong></td><td>核心</td><td>專案鎖定 ^18.x</td></tr><tr><td><strong>@types/react</strong>, <strong>@types/react-dom</strong></td><td>型別</td><td>應與 react 大版一致（18.x）</td></tr></tbody></table><hr><h2 id="測試與建置-間接依賴-react" tabindex="-1">測試與建置（間接依賴 React） <a class="header-anchor" href="#測試與建置-間接依賴-react" aria-label="Permalink to &quot;測試與建置（間接依賴 React）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>套件</th><th>用途</th><th>React 支援／備註</th></tr></thead><tbody><tr><td><strong>@testing-library/react</strong></td><td>元件測試</td><td>v13+ 要求 React 18；v16 與 React 18 相容，需 peer @testing-library/dom</td></tr><tr><td><strong>@testing-library/user-event</strong></td><td>使用者操作模擬</td><td>與 RTL 搭配，無額外 React 版本限制</td></tr><tr><td><strong>vitest</strong></td><td>測試執行</td><td>與 React 版本無直接 peer；透過 RTL 測 React 元件</td></tr><tr><td><strong>msw</strong></td><td>API mock</td><td>無 React peer；Node 18+、Fetch API，與 React 版本無關</td></tr><tr><td><strong>vite</strong></td><td>建置</td><td>無 React peer；Remix 負責 React 整合</td></tr></tbody></table><hr><h2 id="其他關鍵套件" tabindex="-1">其他關鍵套件 <a class="header-anchor" href="#其他關鍵套件" aria-label="Permalink to &quot;其他關鍵套件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>套件</th><th>用途</th><th>React 支援／備註</th></tr></thead><tbody><tr><td><strong>lucide-react</strong></td><td>圖標</td><td>通常支援 React 16+；升級時查 peer</td></tr><tr><td><strong>class-variance-authority</strong></td><td>樣式變體</td><td>無 React peer，僅型別與 runtime 工具</td></tr><tr><td><strong>zod</strong></td><td>契約 schema</td><td>無 React peer；TypeScript / 任何環境皆可</td></tr><tr><td><strong>tailwindcss</strong></td><td>樣式</td><td>無 React peer</td></tr></tbody></table><hr><h2 id="維護方式" tabindex="-1">維護方式 <a class="header-anchor" href="#維護方式" aria-label="Permalink to &quot;維護方式&quot;">​</a></h2><ol><li><strong>新增依賴時</strong>：查 npm 該套件 <code>peerDependencies</code> 是否含 <code>react</code> / <code>react-dom</code>，並在本文「與 React 直接相關」或「其他」補一列。</li><li><strong>升級 React 時</strong>：執行 <code>pnpm run check:peers</code>（即 <code>pnpm ls react react-dom</code>），檢查 peer 衝突；依本表與官方遷移指南逐項驗證。</li><li><strong>升級 Radix / Remix / RTL 時</strong>：查該套件 changelog 的 React 要求，並更新本表與 <a href="./../architecture/system-overview.html">system-overview</a> 的 Tech Stack。</li></ol><hr><h2 id="參考" tabindex="-1">參考 <a class="header-anchor" href="#參考" aria-label="Permalink to &quot;參考&quot;">​</a></h2><ul><li><a href="./../architecture/system-overview.html">system-overview</a>：Tech Stack 寫明 Remix v2 + React 18</li><li><strong>package.json</strong>：<code>engines.node</code>、<code>dependencies.react</code> 為單一來源</li></ul>',22)])])}const R=e(o,[["render",c]]);export{p as __pageData,R as default};
